import { randomUUID } from "node:crypto";
import bcrypt from "bcryptjs";
import { auth } from "@/auth";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
};

type StoredUser = User & {
  passwordHash?: string;
  googleId?: string;
};

// In-memory store (no database in this project yet). Kept on globalThis so dev
// hot reloads don't wipe accounts. Replace with a real DB before production.
const store = globalThis as unknown as { __notelyUsers?: StoredUser[] };
const users = (store.__notelyUsers ??= [
  { id: "1", email: "ada@example.com", name: "Ada", createdAt: "2026-01-04" },
  { id: "2", email: "grace@example.com", name: "Grace", createdAt: "2026-02-11" },
]);

const normalizeEmail = (email: string) => email.trim().toLowerCase();

function toUser({ id, email, name, createdAt }: StoredUser): User {
  return { id, email, name, createdAt };
}

export async function listUsers(): Promise<User[]> {
  return users.map(toUser);
}

export async function getUser(id: string): Promise<User | undefined> {
  const u = users.find((u) => u.id === id);
  return u && toUser(u);
}

export async function getUserByEmail(email: string): Promise<User | undefined> {
  const e = normalizeEmail(email);
  const u = users.find((u) => u.email === e);
  return u && toUser(u);
}

export class EmailTakenError extends Error {}

export async function createUserWithPassword(input: {
  email: string;
  name: string;
  password: string;
}): Promise<User> {
  const email = normalizeEmail(input.email);
  if (users.some((u) => u.email === email)) throw new EmailTakenError();
  const user: StoredUser = {
    id: randomUUID(),
    email,
    name: input.name.trim(),
    createdAt: new Date().toISOString().slice(0, 10),
    passwordHash: await bcrypt.hash(input.password, 12),
  };
  users.push(user);
  return toUser(user);
}

// Dummy hash so unknown emails cost the same as wrong passwords (timing).
const DUMMY_HASH = bcrypt.hashSync("not-a-real-password", 12);

export async function verifyPassword(
  email: string,
  password: string,
): Promise<User | null> {
  const e = normalizeEmail(email);
  const u = users.find((u) => u.email === e);
  const ok = await bcrypt.compare(password, u?.passwordHash ?? DUMMY_HASH);
  return u && u.passwordHash && ok ? toUser(u) : null;
}

// Called only for Google profiles with a verified email. Links to an existing
// account with the same email, otherwise creates one.
export async function findOrCreateGoogleUser(profile: {
  googleId: string;
  email: string;
  name?: string | null;
}): Promise<User> {
  const email = normalizeEmail(profile.email);
  let u =
    users.find((u) => u.googleId === profile.googleId) ??
    users.find((u) => u.email === email);
  if (u) {
    u.googleId ??= profile.googleId;
  } else {
    u = {
      id: randomUUID(),
      email,
      name: profile.name?.trim() || email.split("@")[0],
      createdAt: new Date().toISOString().slice(0, 10),
      googleId: profile.googleId,
    };
    users.push(u);
  }
  return toUser(u);
}

export async function getCurrentUser(): Promise<User | undefined> {
  const session = await auth();
  const id = session?.user?.id;
  return id ? getUser(id) : undefined;
}
